namespace {
constexpr int kEnginePluginApi = 1;
std::string Trim(const std::string& value){const auto first=value.find_first_not_of(" \t\r\n");if(first==std::string::npos)return {};const auto last=value.find_last_not_of(" \t\r\n");return value.substr(first,last-first+1);}
std::string Lower(std::string value){std::transform(value.begin(),value.end(),value.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return value;}
bool Boolean(const std::string& value,bool fallback=false){const auto lower=Lower(Trim(value));if(lower=="true"||lower=="yes"||lower=="1"||lower=="on")return true;if(lower=="false"||lower=="no"||lower=="0"||lower=="off")return false;return fallback;}
const char* TypeName(PluginManagerPanel::Type type){switch(type){case PluginManagerPanel::Type::Runtime:return "Runtime";case PluginManagerPanel::Type::Editor:return "Editor";case PluginManagerPanel::Type::Both:return "Editor + Runtime";case PluginManagerPanel::Type::Content:return "Content only";}return "Unknown";}
std::vector<std::string> Split(const std::string& value){std::vector<std::string> result;std::string item;std::istringstream in(value);while(std::getline(in,item,',')){item=Trim(item);if(!item.empty())result.push_back(item);}return result;}
std::vector<int> Version(const std::string& value){std::vector<int> result;std::string part;std::istringstream in(value);while(std::getline(in,part,'.')){try{result.push_back(std::max(0,std::stoi(part)));}catch(...){result.push_back(0);}}return result;}
bool VersionAtLeast(const std::string& actual,const std::string& minimum){auto a=Version(actual),b=Version(minimum);const auto n=std::max(a.size(),b.size());a.resize(n);b.resize(n);return a>=b;}
bool ValidId(const std::string& id){return !id.empty()&&std::all_of(id.begin(),id.end(),[](unsigned char c){return std::isalnum(c)||c=='_'||c=='-'||c=='.';});}
bool IsWithin(const std::filesystem::path& root,const std::filesystem::path& candidate){std::error_code ec;const auto canonicalRoot=std::filesystem::weakly_canonical(root,ec);if(ec)return false;const auto canonicalCandidate=std::filesystem::weakly_canonical(candidate,ec);if(ec)return false;const auto relative=canonicalCandidate.lexically_relative(canonicalRoot);if(relative.empty())return false;const auto first=relative.begin();return first==relative.end()||*first!="..";}
std::string EscapeCMake(std::string value){std::replace(value.begin(),value.end(),'\\','/');std::string out;for(char c:value){if(c=='"')out+="\\\"";else out+=c;}return out;}
PluginManagerPanel::Dependency ParseDependency(std::string value,bool optional){PluginManagerPanel::Dependency result;result.optional=optional;const auto marker=value.find(">=");if(marker==std::string::npos)result.id=Trim(value);else{result.id=Trim(value.substr(0,marker));result.minimumVersion=Trim(value.substr(marker+2));}return result;}
PluginManagerPanel::Plugin ReadPlugin(const std::filesystem::path& descriptor,PluginManagerPanel::Scope scope){PluginManagerPanel::Plugin plugin;plugin.scope=scope;plugin.descriptor=descriptor;plugin.root=descriptor.parent_path();std::ifstream in(descriptor);if(!in){plugin.errors.push_back("Descriptor cannot be read.");return plugin;}std::unordered_map<std::string,std::string> values;std::string line;while(std::getline(in,line)){const auto hash=line.find('#');if(hash!=std::string::npos)line.erase(hash);const auto equal=line.find('=');if(equal==std::string::npos)continue;values[Lower(Trim(line.substr(0,equal)))]=Trim(line.substr(equal+1));}plugin.id=values["id"];plugin.name=values["name"];plugin.version=values["version"];plugin.author=values["author"];plugin.description=values["description"];plugin.engineApi=1;try{plugin.engineApi=std::stoi(values["engine_api"]);}catch(...){}plugin.required=Boolean(values["required"]);plugin.defaultEnabled=Boolean(values["enabled_by_default"],plugin.required);const auto type=Lower(values["type"]);if(type=="runtime")plugin.type=PluginManagerPanel::Type::Runtime;else if(type=="editor")plugin.type=PluginManagerPanel::Type::Editor;else if(type=="content")plugin.type=PluginManagerPanel::Type::Content;else plugin.type=PluginManagerPanel::Type::Both;for(const auto& value:Split(values["dependencies"]))plugin.dependencies.push_back(ParseDependency(value,false));for(const auto& value:Split(values["optional_dependencies"]))plugin.dependencies.push_back(ParseDependency(value,true));if(!values["cmake_directory"].empty())plugin.cmakeDirectory=plugin.root/values["cmake_directory"];else if(std::filesystem::is_regular_file(plugin.root/"CMakeLists.txt"))plugin.cmakeDirectory=plugin.root;if(!values["binary"].empty())plugin.binary=plugin.root/values["binary"];if(plugin.name.empty())plugin.name=plugin.id;if(!ValidId(plugin.id))plugin.errors.push_back("ID is missing or contains unsupported characters.");if(plugin.version.empty())plugin.errors.push_back("Version is required.");if(plugin.engineApi!=kEnginePluginApi)plugin.errors.push_back("Plugin API "+std::to_string(plugin.engineApi)+" is incompatible with engine API "+std::to_string(kEnginePluginApi)+".");std::error_code ec;if(!plugin.cmakeDirectory.empty()&&!IsWithin(plugin.root,plugin.cmakeDirectory))plugin.errors.push_back("CMake directory must remain inside the plugin folder.");else if(!plugin.cmakeDirectory.empty()&&!std::filesystem::is_regular_file(plugin.cmakeDirectory/"CMakeLists.txt",ec))plugin.errors.push_back("CMake directory has no CMakeLists.txt.");if(!plugin.binary.empty()&&!IsWithin(plugin.root,plugin.binary))plugin.errors.push_back("Declared binary must remain inside the plugin folder.");else if(!plugin.binary.empty()&&!std::filesystem::is_regular_file(plugin.binary,ec))plugin.errors.push_back("Declared plugin binary is missing.");if(plugin.cmakeDirectory.empty()&&plugin.type!=PluginManagerPanel::Type::Content)plugin.errors.push_back("Native plugins require a CMake directory. Binary-only loading is not supported by plugin API 1.");return plugin;}
}

PluginManagerPanel::~PluginManagerPanel(){if(m_future.valid())m_future.wait();}
void PluginManagerPanel::StartScan(const std::filesystem::path& engineRoot,const std::filesystem::path& projectRoot,const std::filesystem::path& projectFile){if(m_scanning){m_rescanRequested=true;m_pendingEngineRoot=engineRoot;m_pendingProjectRoot=projectRoot;m_pendingProjectFile=projectFile;return;}m_rescanRequested=false;m_scanning=true;m_status="Discovering plugins...";m_future=std::async(std::launch::async,[engineRoot,projectRoot,projectFile](){ScanResult result;engine::Config config(projectFile.string());for(const auto& search:std::array<std::pair<std::filesystem::path,Scope>,2>{{{engineRoot/"Plugins",Scope::Engine},{projectRoot/"Plugins",Scope::Project}}}){std::error_code ec;if(!std::filesystem::is_directory(search.first,ec))continue;for(std::filesystem::recursive_directory_iterator it(search.first,std::filesystem::directory_options::skip_permission_denied,ec),end;!ec&&it!=end;it.increment(ec)){if(!it->is_regular_file(ec)||Lower(it->path().extension().string())!=".3dgplugin")continue;auto plugin=ReadPlugin(it->path(),search.second);plugin.enabled=config.GetBool("plugins."+plugin.id+".enabled",plugin.defaultEnabled);if(plugin.required)plugin.enabled=true;plugin.stagedEnabled=plugin.enabled;result.plugins.push_back(std::move(plugin));}if(ec&&!result.error.empty())result.error+="\n";if(ec)result.error+="Could not fully scan "+search.first.string()+": "+ec.message();}std::sort(result.plugins.begin(),result.plugins.end(),[](const Plugin& a,const Plugin& b){return std::pair(Lower(a.name),a.id)<std::pair(Lower(b.name),b.id);});return result;});}
void PluginManagerPanel::Poll(){if(!m_scanning||!m_future.valid()||m_future.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready)return;try{auto result=m_future.get();m_plugins=std::move(result.plugins);m_status=result.error.empty()?std::to_string(m_plugins.size())+" plugin(s) discovered.":result.error;Validate();}catch(const std::exception& e){m_status=std::string("Plugin discovery failed: ")+e.what();}m_selected=m_plugins.empty()?-1:std::clamp(m_selected,0,static_cast<int>(m_plugins.size())-1);m_scanning=false;if(m_rescanRequested){const auto engineRoot=m_pendingEngineRoot,projectRoot=m_pendingProjectRoot,projectFile=m_pendingProjectFile;StartScan(engineRoot,projectRoot,projectFile);}}
void PluginManagerPanel::Validate(){
    for(auto& plugin:m_plugins){plugin.errors.erase(std::remove_if(plugin.errors.begin(),plugin.errors.end(),[](const std::string& value){return value.rfind("Dependency ",0)==0||value.rfind("Duplicate plugin ID",0)==0||value=="Dependency cycle detected.";}),plugin.errors.end());}
    std::unordered_map<std::string,std::vector<int>> ids;for(int i=0;i<static_cast<int>(m_plugins.size());++i)ids[Lower(m_plugins[static_cast<std::size_t>(i)].id)].push_back(i);for(const auto& [id,indices]:ids)if(indices.size()>1)for(int index:indices)m_plugins[static_cast<std::size_t>(index)].errors.push_back("Duplicate plugin ID: "+id);
    for(auto& plugin:m_plugins)if(plugin.stagedEnabled)for(const auto& dependency:plugin.dependencies){auto found=ids.find(Lower(dependency.id));if(found==ids.end()){if(!dependency.optional)plugin.errors.push_back("Dependency "+dependency.id+" is missing.");continue;}const auto& target=m_plugins[static_cast<std::size_t>(found->second.front())];if(!target.stagedEnabled&&!dependency.optional)plugin.errors.push_back("Dependency "+dependency.id+" is disabled.");if(!dependency.minimumVersion.empty()&&!VersionAtLeast(target.version,dependency.minimumVersion))plugin.errors.push_back("Dependency "+dependency.id+" requires version >= "+dependency.minimumVersion+".");}
    enum class Mark{White,Gray,Black};std::vector<Mark> marks(m_plugins.size(),Mark::White);std::vector<int> stack;std::unordered_set<int> cyclic;std::function<void(int)> visit=[&](int index){marks[index]=Mark::Gray;stack.push_back(index);for(const auto& dep:m_plugins[static_cast<std::size_t>(index)].dependencies){auto found=ids.find(Lower(dep.id));if(found==ids.end())continue;const int next=found->second.front();if(!m_plugins[static_cast<std::size_t>(next)].stagedEnabled)continue;if(marks[next]==Mark::White)visit(next);else if(marks[next]==Mark::Gray){auto start=std::find(stack.begin(),stack.end(),next);for(;start!=stack.end();++start)cyclic.insert(*start);}}stack.pop_back();marks[index]=Mark::Black;};for(int i=0;i<static_cast<int>(m_plugins.size());++i)if(m_plugins[static_cast<std::size_t>(i)].stagedEnabled&&marks[i]==Mark::White)visit(i);for(int index:cyclic)m_plugins[static_cast<std::size_t>(index)].errors.push_back("Dependency cycle detected.");
}
bool PluginManagerPanel::HasPendingChanges()const{return std::any_of(m_plugins.begin(),m_plugins.end(),[](const Plugin& plugin){return plugin.enabled!=plugin.stagedEnabled;});}
bool PluginManagerPanel::Apply(const std::filesystem::path& projectRoot,const std::filesystem::path& projectFile){Validate();for(const auto& plugin:m_plugins)if(plugin.stagedEnabled&&!plugin.errors.empty()){m_status="Cannot apply: resolve enabled plugin errors first.";return false;}std::error_code ec;if(projectFile.empty()||!std::filesystem::is_regular_file(projectFile,ec)){m_status="Open or create a saved project before changing plugins.";return false;}const auto generatedRoot=projectRoot/"Intermediate"/"Plugins";std::filesystem::create_directories(generatedRoot,ec);if(ec){m_status="Could not create plugin integration folder: "+ec.message();return false;}const auto cmakePath=generatedRoot/"EnabledPlugins.cmake",cmakeTemp=generatedRoot/"EnabledPlugins.cmake.tmp";{std::ofstream out(cmakeTemp);if(!out){m_status="Could not write generated plugin integration.";return false;}out<<"# Generated by 3DG Editor Plugin Manager. Do not edit.\nset(THREEDG_ENABLED_PLUGIN_DIRS)\n";for(const auto& plugin:m_plugins)if(plugin.stagedEnabled&&!plugin.cmakeDirectory.empty())out<<"list(APPEND THREEDG_ENABLED_PLUGIN_DIRS \""<<EscapeCMake(std::filesystem::absolute(plugin.cmakeDirectory).string())<<"\")\n";if(!out){m_status="Could not finish generated plugin integration.";return false;}}
    engine::Config config(projectFile.string());for(const auto& plugin:m_plugins)config.Set("plugins."+plugin.id+".enabled",plugin.stagedEnabled);const auto configTemp=projectFile.parent_path()/(projectFile.filename().string()+".plugins.tmp");if(!config.Save(configTemp.string())){std::filesystem::remove(cmakeTemp,ec);m_status="Could not write updated project plugin settings.";return false;}const auto configBackup=projectFile.parent_path()/(projectFile.filename().string()+".plugins.backup");std::filesystem::copy_file(projectFile,configBackup,std::filesystem::copy_options::overwrite_existing,ec);if(ec){std::filesystem::remove(cmakeTemp,ec);std::filesystem::remove(configTemp,ec);m_status="Could not back up project settings: "+ec.message();return false;}std::filesystem::remove(projectFile,ec);if(ec){std::filesystem::remove(cmakeTemp,ec);std::filesystem::remove(configTemp,ec);m_status="Could not replace project plugin settings: "+ec.message();return false;}std::filesystem::rename(configTemp,projectFile,ec);if(ec){std::error_code restoreEc;std::filesystem::copy_file(configBackup,projectFile,std::filesystem::copy_options::overwrite_existing,restoreEc);std::filesystem::remove(cmakeTemp,restoreEc);std::filesystem::remove(configTemp,restoreEc);m_status="Could not publish project plugin settings; the original was restored: "+ec.message();return false;}std::filesystem::remove(cmakePath,ec);ec.clear();std::filesystem::rename(cmakeTemp,cmakePath,ec);if(ec){std::error_code restoreEc;std::filesystem::copy_file(configBackup,projectFile,std::filesystem::copy_options::overwrite_existing,restoreEc);m_status="Could not publish plugin build integration; project settings were restored.";return false;}std::filesystem::remove(configBackup,ec);for(auto& plugin:m_plugins)plugin.enabled=plugin.stagedEnabled;m_status="Plugin settings applied. Rebuild and restart the editor for native changes.";return true;}

void PluginManagerPanel::Draw(const std::filesystem::path& engineRoot,const std::filesystem::path& projectRoot,const std::filesystem::path& projectFile,bool* open){Poll();if(!m_initialized||m_projectRoot!=projectRoot){m_initialized=true;m_projectRoot=projectRoot;StartScan(engineRoot,projectRoot,projectFile);}if(!ImGui::Begin(EditorPanels::Name(EditorPanels::Panel::PluginManager),open)){ImGui::End();return;}if(ImGui::Button("Refresh"))StartScan(engineRoot,projectRoot,projectFile);ImGui::SameLine();ImGui::BeginDisabled(m_scanning||!HasPendingChanges());if(ImGui::Button("Apply Changes"))Apply(projectRoot,projectFile);ImGui::EndDisabled();ImGui::SameLine();if(m_scanning)ImGui::TextDisabled("Scanning...");else ImGui::TextWrapped("%s",m_status.c_str());ImGui::TextDisabled("Searches Engine/Plugins and <Project>/Plugins for .3dgplugin descriptors.");ImGui::SetNextItemWidth(240);ImGui::InputTextWithHint("##plugin_filter","Search name, ID, author, or description",m_filter,sizeof(m_filter));ImGui::SameLine();ImGui::Checkbox("Enabled only",&m_enabledOnly);ImGui::SameLine();ImGui::Checkbox("Issues only",&m_issuesOnly);ImGui::Separator();const float left=std::min(430.0f,ImGui::GetContentRegionAvail().x*.45f);ImGui::BeginChild("PluginManagerList",{left,0},true);const std::string filter=Lower(m_filter);for(int i=0;i<static_cast<int>(m_plugins.size());++i){auto& plugin=m_plugins[static_cast<std::size_t>(i)];if(m_enabledOnly&&!plugin.stagedEnabled)continue;if(m_issuesOnly&&plugin.errors.empty()&&plugin.warnings.empty())continue;if(!filter.empty()&&Lower(plugin.name+" "+plugin.id+" "+plugin.author+" "+plugin.description).find(filter)==std::string::npos)continue;ImGui::PushID(i);bool enabled=plugin.stagedEnabled;ImGui::BeginDisabled(plugin.required);if(ImGui::Checkbox("##enabled",&enabled)){plugin.stagedEnabled=enabled;Validate();}ImGui::EndDisabled();ImGui::SameLine();const bool selected=m_selected==i;const std::string label=plugin.name+"  "+plugin.version+"##plugin";if(ImGui::Selectable(label.c_str(),selected))m_selected=i;ImGui::SameLine();if(!plugin.errors.empty())ImGui::TextColored({1,.3f,.25f,1},"Error");else if(!plugin.warnings.empty())ImGui::TextColored({1,.7f,.2f,1},"Review");else ImGui::TextDisabled("%s",plugin.scope==Scope::Engine?"Engine":"Project");ImGui::PopID();}if(m_plugins.empty()&&!m_scanning)ImGui::TextDisabled("No plugins found.");ImGui::EndChild();ImGui::SameLine();ImGui::BeginChild("PluginManagerDetails",{0,0},true);if(m_selected>=0&&m_selected<static_cast<int>(m_plugins.size())){const auto& plugin=m_plugins[static_cast<std::size_t>(m_selected)];ImGui::Text("%s",plugin.name.c_str());ImGui::TextDisabled("%s  |  %s  |  API %d",plugin.id.c_str(),plugin.version.c_str(),plugin.engineApi);ImGui::Text("Type: %s",TypeName(plugin.type));ImGui::Text("Scope: %s",plugin.scope==Scope::Engine?"Engine":"Project");if(!plugin.author.empty())ImGui::Text("Author: %s",plugin.author.c_str());ImGui::TextWrapped("%s",plugin.description.empty()?"No description supplied.":plugin.description.c_str());ImGui::SeparatorText("State");if(plugin.required)ImGui::TextUnformatted("Required: always enabled");if(plugin.enabled!=plugin.stagedEnabled)ImGui::TextColored({1,.7f,.2f,1},"Pending: %s",plugin.stagedEnabled?"enable":"disable");else ImGui::Text("Project setting: %s",plugin.enabled?"Enabled":"Disabled");if(plugin.type==Type::Content)ImGui::TextDisabled("Content behavior is defined by the plugin; restart after applying.");else ImGui::TextColored({1,.7f,.2f,1},"Native change requires project rebuild and editor restart.");ImGui::SeparatorText("Dependencies");if(plugin.dependencies.empty())ImGui::TextDisabled("None");for(const auto& dependency:plugin.dependencies)ImGui::BulletText("%s%s%s",dependency.id.c_str(),dependency.minimumVersion.empty()?"":" >= ",dependency.minimumVersion.c_str());ImGui::SeparatorText("Files");ImGui::TextWrapped("Descriptor: %s",plugin.descriptor.string().c_str());if(!plugin.cmakeDirectory.empty())ImGui::TextWrapped("CMake: %s",plugin.cmakeDirectory.string().c_str());if(!plugin.binary.empty())ImGui::TextWrapped("Binary: %s",plugin.binary.string().c_str());if(!plugin.errors.empty()){ImGui::SeparatorText("Errors");for(const auto& error:plugin.errors)ImGui::TextColored({1,.3f,.25f,1},"- %s",error.c_str());}if(!plugin.warnings.empty()){ImGui::SeparatorText("Warnings");for(const auto& warning:plugin.warnings)ImGui::TextColored({1,.7f,.2f,1},"- %s",warning.c_str());}}else ImGui::TextDisabled("Select a plugin to inspect it.");ImGui::EndChild();ImGui::End();}
